import{_ as n,a0 as p,w as o,s as d,ao as r,I as l,x as s,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何使用 GPG 加解密文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 GPG 加解密文件 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 GPG 加解密文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 GPG 加解密文件 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171024 How to Encrypt and Decrypt Individual Files With GPG","title":"如何使用 GPG 加解密文件","tag":"201712","desc":""},"relativePath":"201712/20171024 How to Encrypt and Decrypt Individual Files With GPG.md","filePath":"[post].md"}'),h={name:"201712/20171024 How to Encrypt and Decrypt Individual Files With GPG.md"};function g(k,i,c,u,b,f){const t=p("Link");return o(),d("div",null,[i[13]||(i[13]=r('<h1 id="如何使用-gpg-加解密文件" tabindex="-1">如何使用 GPG 加解密文件 <a class="header-anchor" href="#如何使用-gpg-加解密文件" aria-label="Permalink to “如何使用 GPG 加解密文件”">​</a></h1><p>目標：使用 GPG 加密文件</p><p>發行版：適用於任何發行版</p><p>要求：安裝了 GPG 的 Linux 或者擁有 root 權限來安裝它。</p><p>難度：簡單</p><p>約定：</p><ul><li><code>#</code> - 需要使用 root 權限來執行指定命令，可以直接使用 root 用户來執行，也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 可以使用普通用户來執行指定命令</li></ul><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>加密非常重要。它對於保護敏感信息來説是必不可少的。你的私人文件應該要被加密，而 GPG 提供了很好的解決方案。</p><h3 id="安裝-gpg" tabindex="-1">安裝 GPG <a class="header-anchor" href="#安裝-gpg" aria-label="Permalink to “安裝 GPG”">​</a></h3><p>GPG 的使用非常廣泛。你在幾乎每個發行版的倉庫中都能找到它。如果你還沒有安裝它，那現在就來安裝一下吧。</p><p><strong>Debian/Ubuntu</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gnupg</span></span></code></pre></div><p><strong>Fedora</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install gnupg2</span></span></code></pre></div><p><strong>Arch</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S gnupg</span></span></code></pre></div><p><strong>Gentoo</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># emerge --ask app-crypt/gnupg</span></span></code></pre></div><h3 id="創建密鑰" tabindex="-1">創建密鑰 <a class="header-anchor" href="#創建密鑰" aria-label="Permalink to “創建密鑰”">​</a></h3><p>你需要一個密鑰對來加解密文件。如果你為 SSH 已經生成過了密鑰對，那麼你可以直接使用它。如果沒有，GPG 包含工具來生成密鑰對。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --full-generate-key</span></span></code></pre></div><p>GPG 有一個命令列程序可以幫你一步一步的生成密鑰。它還有一個簡單得多的工具，但是這個工具不能讓你設置密鑰類型，密鑰的長度以及過期時間，因此不推薦使用這個工具。</p><p>GPG 首先會詢問你密鑰的類型。沒什麼特別的話選擇默認值就好。</p><p>下一步需要設置密鑰長度。<code>4096</code> 是一個不錯的選擇。</p><p>之後，可以設置過期的日期。 如果希望密鑰永不過期則設置為 <code>0</code>。</p><p>然後，輸入你的名稱。</p><p>最後，輸入電子郵件地址。</p><p>如果你需要的話，還能添加一個註釋。</p><p>所有這些都完成後，GPG 會讓你校驗一下這些信息。</p><p>GPG 還會問你是否需要為密鑰設置密碼。這一步是可選的， 但是會增加保護的程度。若需要設置密碼，則 GPG 會收集你的操作信息來增加密鑰的健壯性。 所有這些都完成後， GPG 會顯示密鑰相關的信息。</p><h3 id="加密的基本方法" tabindex="-1">加密的基本方法 <a class="header-anchor" href="#加密的基本方法" aria-label="Permalink to “加密的基本方法”">​</a></h3><p>現在你擁有了自己的密鑰，加密文件非常簡單。 使用下面的命令在 <code>/tmp</code> 目錄中創建一個空白文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch /tmp/test.txt</span></span></code></pre></div><p>然後用 GPG 來加密它。這裏 <code>-e</code> 標誌告訴 GPG 你想要加密文件， <code>-r</code> 標誌指定接收者。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -e -r &quot;Your Name&quot; /tmp/test.txt</span></span></code></pre></div><p>GPG 需要知道這個文件的接收者和發送者。由於這個文件給是你的，因此無需指定發送者，而接收者就是你自己。</p><h3 id="解密的基本方法" tabindex="-1">解密的基本方法 <a class="header-anchor" href="#解密的基本方法" aria-label="Permalink to “解密的基本方法”">​</a></h3><p>你收到加密文件後，就需要對它進行解密。 你無需指定解密用的密鑰。 這個信息被編碼在文件中。 GPG 會嘗試用其中的密鑰進行解密。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -d /tmp/test.txt.gpg</span></span></code></pre></div><h3 id="發送文件" tabindex="-1">發送文件 <a class="header-anchor" href="#發送文件" aria-label="Permalink to “發送文件”">​</a></h3><p>假設你需要發送文件給別人。你需要有接收者的公鑰。 具體怎麼獲得密鑰由你自己決定。 你可以讓他們直接把公鑰發送給你， 也可以通過密鑰服務器來獲取。</p><p>收到對方公鑰後，導入公鑰到 GPG 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --import yourfriends.key</span></span></code></pre></div><p>這些公鑰與你自己創建的密鑰一樣，自帶了名稱和電子郵件地址的信息。 記住，為了讓別人能解密你的文件，別人也需要你的公鑰。 因此導出公鑰並將之發送出去。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg --export -a &quot;Your Name&quot; &gt; your.key</span></span></code></pre></div><p>現在可以開始加密要發送的文件了。它跟之前的步驟差不多， 只是需要指定你自己為發送人。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -e -u &quot;Your Name&quot; -r &quot;Their Name&quot; /tmp/test.txt</span></span></code></pre></div><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>就這樣了。GPG 還有一些高級選項， 不過你在 99% 的時間內都不會用到這些高級選項。 GPG 就是這麼易於使用。你也可以使用創建的密鑰對來發送和接受加密郵件，其步驟跟上面演示的差不多， 不過大多數的電子郵件客户端在擁有密鑰的情況下會自動幫你做這個動作。</p><hr>',51)),l("p",null,[i[1]||(i[1]=s("via: ",-1)),e(t,{href:"https://linuxconfig.org/how-to-encrypt-and-decrypt-individual-files-with-gpg"},{default:a(()=>[...i[0]||(i[0]=[s("https://linuxconfig.org/how-to-encrypt-and-decrypt-individual-files-with-gpg",-1)])]),_:1})]),l("p",null,[i[5]||(i[5]=s("作者：",-1)),e(t,{href:"https://linuxconfig.org"},{default:a(()=>[...i[2]||(i[2]=[s("Nick Congleton",-1)])]),_:1}),i[6]||(i[6]=s(" 譯者：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[3]||(i[3]=[s("lujun9972",-1)])]),_:1}),i[7]||(i[7]=s(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[4]||(i[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[i[10]||(i[10]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[8]||(i[8]=[s("LCTT",-1)])]),_:1}),i[11]||(i[11]=s(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...i[9]||(i[9]=[s("Linux 中國",-1)])]),_:1}),i[12]||(i[12]=s(" 榮譽推出",-1))])])}const P=n(h,[["render",g]]);export{m as __pageData,P as default};
